mapper.select:
SELECT COUNT(1) AS totalMembers, SUM(CASE WHEN m.create_time >= CURDATE() AND m.create_time < DATE_ADD(CURDATE(), INTERVAL 1 DAY) THEN 1 ELSE 0 END) AS todayMembers, SUM(CASE WHEN EXISTS (SELECT 1 FROM mem_points_record pr WHERE pr.member_id = m.member_id AND pr.del_flag = '0' AND pr.create_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)) OR EXISTS (SELECT 1 FROM mem_points_exchange pe WHERE pe.member_id = m.member_id AND pe.del_flag = '0' AND pe.create_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)) OR EXISTS (SELECT 1 FROM mem_seckill_record sr WHERE sr.member_id = m.member_id AND sr.del_flag = '0' AND sr.create_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)) THEN 1 ELSE 0 END) AS activeMembers FROM mem_member m WHERE m.del_flag = '0'
AND m.tenant_id = #{tenantId}
AND m.dept_id IN #{d}

SELECT
    (SELECT COUNT(1) FROM mem_member_sign_in s
        WHERE s.del_flag = '0'
        AND s.tenant_id = #{tenantId}

            AND s.dept_id IN
            #{d}

        AND s.sign_date = CURDATE()
    ) AS todaySignInCount,
    (SELECT COALESCE(AVG(m.growth_value), 0) FROM mem_member m
        WHERE m.del_flag = '0'
        AND m.tenant_id = #{tenantId}

            AND m.dept_id IN
            #{d}

    ) AS avgGrowthValue,
    (SELECT COUNT(1) FROM member_growth_action a
        WHERE a.del_flag = '0'
        AND a.tenant_id = #{tenantId}

            AND a.dept_id IN
            #{d}

        AND a.status = '0'
    ) AS pendingGrowthActions,
    (SELECT COUNT(1) FROM member_growth_action a
        WHERE a.del_flag = '0'
        AND a.tenant_id = #{tenantId}

            AND a.dept_id IN
            #{d}

        AND a.status = '1'
    ) AS completedGrowthActions,
    (SELECT COUNT(1) FROM member_growth_action a
        WHERE a.del_flag = '0'
        AND a.tenant_id = #{tenantId}

            AND a.dept_id IN
            #{d}

    ) AS totalGrowthActions
FROM dual

SELECT
    (SELECT COALESCE(SUM(CASE WHEN m.available_points > 0 THEN m.available_points ELSE 0 END), 0)
        FROM mem_member m
        WHERE m.del_flag = '0'
        AND m.tenant_id = #{tenantId}

            AND m.dept_id IN
            #{d}

    ) AS totalAvailablePoints,
    (SELECT COALESCE(SUM(pr.points), 0) FROM mem_points_record pr
        WHERE pr.del_flag = '0' AND pr.points > 0

            AND pr.dept_id IN
            #{d}

        AND pr.create_time >= CURDATE() AND pr.create_time < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
    ) AS todayPointsIssued,
    (SELECT COALESCE(SUM(ABS(pr.points)), 0) FROM mem_points_record pr
        WHERE pr.del_flag = '0' AND pr.points < 0

            AND pr.dept_id IN
            #{d}

        AND pr.create_time >= CURDATE() AND pr.create_time < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
    ) AS todayPointsConsumed,
    (SELECT COUNT(1) FROM mem_points_exchange pe
        WHERE pe.del_flag = '0' AND pe.status = '0'

            AND pe.dept_id IN
            #{d}

    ) AS pendingExchangeCount
FROM dual

SELECT COALESCE(ct.type_name, CASE m.card_type WHEN '0' THEN '普通会员' WHEN '1' THEN '银卡会员' WHEN '2' THEN '金卡会员' WHEN '3' THEN '钻石会员' ELSE COALESCE(m.card_type, '未分级') END ) AS levelName, COUNT(1) AS count FROM mem_member m LEFT JOIN mem_member_card_type ct ON ct.type_code = m.card_type AND ct.del_flag = '0' AND ct.tenant_id = #{tenantId} WHERE m.del_flag = '0' AND m.tenant_id = #{tenantId}
AND m.dept_id IN #{d}
GROUP BY levelName ORDER BY count DESC

SELECT segmentName, SUM(cnt) AS count FROM ( SELECT '高价值会员' AS segmentName, COUNT(1) AS cnt FROM mem_member m WHERE m.del_flag = '0' AND m.growth_value >= 1000 AND m.tenant_id = #{tenantId}
AND m.dept_id IN #{d}
UNION ALL SELECT '活跃会员' AS segmentName, COUNT(1) AS cnt FROM mem_member m WHERE m.del_flag = '0' AND m.growth_value < 1000 AND ( EXISTS (SELECT 1 FROM mem_points_record pr WHERE pr.member_id = m.member_id AND pr.del_flag = '0' AND pr.create_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)) OR EXISTS (SELECT 1 FROM mem_points_exchange pe WHERE pe.member_id = m.member_id AND pe.del_flag = '0' AND pe.create_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)) OR EXISTS (SELECT 1 FROM mem_seckill_record sr WHERE sr.member_id = m.member_id AND sr.del_flag = '0' AND sr.create_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)) ) AND m.tenant_id = #{tenantId}
AND m.dept_id IN #{d}
UNION ALL SELECT '沉默会员' AS segmentName, COUNT(1) AS cnt FROM mem_member m WHERE m.del_flag = '0' AND m.growth_value < 1000 AND NOT EXISTS (SELECT 1 FROM mem_points_record pr WHERE pr.member_id = m.member_id AND pr.del_flag = '0' AND pr.create_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)) AND NOT EXISTS (SELECT 1 FROM mem_points_exchange pe WHERE pe.member_id = m.member_id AND pe.del_flag = '0' AND pe.create_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)) AND NOT EXISTS (SELECT 1 FROM mem_seckill_record sr WHERE sr.member_id = m.member_id AND sr.del_flag = '0' AND sr.create_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)) AND m.tenant_id = #{tenantId}
AND m.dept_id IN #{d}
) t GROUP BY segmentName ORDER BY count DESC

SELECT
    (SELECT COUNT(1) FROM mem_seckill s
        WHERE s.del_flag = '0' AND s.status = '0'

            AND s.dept_id IN
            #{d}

    ) AS activeSeckillCount,
    (SELECT COUNT(DISTINCT sr.member_id) FROM mem_seckill_record sr
        WHERE sr.del_flag = '0'

            AND sr.dept_id IN
            #{d}

        AND sr.create_time >= CURDATE() AND sr.create_time < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
    ) AS todayActivityMembers,
    (SELECT COALESCE(SUM(sr.total_amount), 0) FROM mem_seckill_record sr
        WHERE sr.del_flag = '0'

            AND sr.dept_id IN
            #{d}

        AND sr.create_time >= CURDATE() AND sr.create_time < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
    ) AS todayActivityAmount
FROM dual

SELECT
    (SELECT COALESCE(SUM(sale_amount), 0) FROM fin_sale_record
        WHERE del_flag = '0'

            AND dept_id IN
            #{d}

        AND sale_date >= CURDATE() AND sale_date < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
    ) AS todaySale,
    (SELECT COALESCE(SUM(expense_amount), 0) FROM fin_expense
        WHERE del_flag = '0'

            AND dept_id IN
            #{d}

        AND expense_date >= CURDATE() AND expense_date < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
    ) AS todayExpense,
    (SELECT COALESCE(SUM(expense_amount), 0) FROM fin_expense
        WHERE del_flag = '0' AND status = '0'

            AND dept_id IN
            #{d}

    ) AS unverifiedExpense,
    (SELECT COALESCE(SUM(advance_amount), 0) FROM fin_advance
        WHERE del_flag = '0' AND status = '0'

            AND dept_id IN
            #{d}

    ) AS unverifiedAdvance
FROM dual
